'use strict';
// Research-informed support pathways. No diagnosis, name, voice, or remote progress data.
const senEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let senProgress={};try{const p=JSON.parse(localStorage.getItem('spotmatch-support-v1')||'{}');if(p&&typeof p==='object'&&!Array.isArray(p))senProgress=p;}catch{}
let senState=null,senActive=null;
function senSave(){try{localStorage.setItem('spotmatch-support-v1',JSON.stringify(senProgress));}catch{}}
function senDone(key){return supportPathways[key].games.filter((_,i)=>senProgress[key]?.[i]?.complete).length;}
function senPicture(p){if(p?.type==='position'&&p.object==='rabbit'&&p.reference==='box'){const pos=p.position;const y=pos==='on'?7:pos==='in'?56:123;const h=pos==='under'?55:68;let b='<path d="M69 123H172M73 123V177M168 123V177" fill="none" stroke="#a6aa8b" stroke-width="4"/>';b+='<path d="M78 83L99 68H151L173 83V120H78Z" fill="#d4b58b" stroke="#355447" stroke-width="2.5"/><path d="M78 83H173M125 83V120" fill="none" stroke="#355447" stroke-width="2"/>';b+=`<svg x="100" y="${y}" width="46" height="${h}" viewBox="0 -12 116 178">${friendlyAnimal('rabbit')}</svg>`;if(pos==='in')b+='<path d="M79 96H172V120H79Z" fill="#d4b58b" stroke="#355447" stroke-width="2"/>';return sceneFrame(b);}return adultPicture(p);}
function senCover(key){return friendlyCover(supportPathways[key].cover);}
function senCard(key){const c=supportPathways[key];return `<button class="library-card story-course-card sen-course-card" data-pathway="${key}" style="--course-tint:${c.color}"><div class="library-card-art">${senCover(key)}<span class="adult-badge">Play together</span></div><div class="story-course-copy"><span class="card-num">10 LITTLE GAMES · SUPPORT PATHWAY</span><h2>${c.name}</h2><p>${c.line}</p><span class="sen-audience">For grown-ups · ${c.audience}</span><span class="library-card-foot"><span>${senDone(key)?`${senDone(key)} explored`:'Find your way to play'}</span><b aria-hidden="true">→</b></span></div></button>`;}
function senBindNav(){document.querySelector('#libraryNav').onclick=libraryHome;document.querySelector('#brand').onclick=e=>{e.preventDefault();libraryHome();};document.querySelector('#courseNav').onclick=()=>senHome(senActive);document.querySelector('#guideNav').onclick=()=>{senHome(senActive);const el=document.querySelector('#senAbout');el.open=true;el.scrollIntoView();};}
const senOriginalLibrary=libraryHome;
libraryHome=function(){senActive=null;senOriginalLibrary();const section=document.createElement('section');section.id='support-pathways';section.className='sen-library';section.innerHTML=`<div class="section-head"><div><span class="eyebrow">A LITTLE EXTRA SUPPORT</span><h2>Different ways to grow.</h2></div><span class="micro">6 pathways · 60 games</span></div><p class="sen-intro">Choose a skill your child would enjoy practising. These pathways offer extra guidance for different learning and access needs. No diagnosis is needed to play.</p><div class="library-grid">${Object.keys(supportPathways).map(senCard).join('')}</div><p class="note">An adult joins every pathway. Research-informed practice, not treatment. Keep appropriate reading instruction and your child’s usual communication support available.</p>`;app.append(section);const shortcut=document.createElement('a');shortcut.href='#support-pathways';shortcut.className='sen-shortcut';shortcut.textContent='Explore six supportive learning pathways ↓';app.querySelector('.welcome-copy')?.append(shortcut);section.querySelectorAll('[data-pathway]').forEach(b=>b.onclick=()=>senHome(b.dataset.pathway));const count=app.querySelector('#course-library .section-head>.micro');if(count)count.textContent='7 original courses · 145 games';};
function senResearch(c){return `<h3>What the evidence supports</h3><p>${senEscape(c.evidence)}</p><p>These games adapt teaching principles from the sources below. The app and this particular course sequence have not been evaluated as an intervention.</p><ul class="sen-sources">${c.sources.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${senEscape(s.title)} ↗</a><p>${senEscape(s.note)}</p></li>`).join('')}</ul>`;}
function senHome(key){senActive=key;activeLearningCourse=null;const c=supportPathways[key];const done=senDone(key);app.innerHTML=`<div class="play-top"><button class="back" id="senLibrary">← Our adventures</button><span class="together-note">♧ Play together <span class="together-explain">An adult supports every game.</span></span></div><section class="course-hero friendly-course-hero" style="--course-tint:${c.color}"><div><span class="eyebrow">A SUPPORTIVE LEARNING PATHWAY</span><h1>${c.name}</h1><p>${c.line}</p><button class="primary" id="senStart">Let’s explore →</button><span class="micro course-smallprint">10 games · Start anywhere · No hurry</span></div><div class="course-hero-art" aria-hidden="true">${senCover(key)}</div></section><details class="course-about" id="senAbout"><summary><span>For grown-ups</span><span class="about-subtitle">${c.audience} · The need, our goal, adaptations & research</span><span aria-hidden="true">＋</span></summary><div class="sen-parent-copy"><h3>What can be difficult?</h3>${c.problem.map(p=>`<p>${senEscape(p)}</p>`).join('')}<h3>Our goal</h3><p>${senEscape(c.goal)}</p><label class="comfort-control"><input id="senLargerPictures" type="checkbox" ${largerPictures?'checked':''}><span><b>A little more room</b><small>Larger pictures and more space between choices.</small></span></label><h3>Adult support & ways to answer</h3><p>${senEscape(c.adapt)}</p><h3>What to notice</h3><p>${senEscape(c.progress)}</p><p class="about-limits">${senEscape(c.limit)}</p>${senResearch(c)}<p class="micro">Choose by observed need, not a diagnosis alone. Courses can overlap. Children do not need to finish prereading games before receiving appropriate reading instruction.</p></div></details><section id="senJourney"><div class="section-head"><div><span class="eyebrow">SMALL DISCOVERIES, TOGETHER</span><h2>Pick a game.</h2></div><span class="micro">${done} of 10 explored</span></div><div class="grid friendly-game-grid">${c.games.map((g,i)=>`<button class="course-card ${senProgress[key]?.[i]?.complete?'completed':''}" data-sen-game="${i}"><div class="thumb" style="--tint:${c.color}">${senGameArt(key,i)}${senProgress[key]?.[i]?.complete?'<span class="played-mark" aria-label="Explored">✓</span>':''}</div><span class="card-num">${String(i+1).padStart(2,'0')}</span><h3>${g.title}</h3><span class="card-bottom">${senProgress[key]?.[i]?.complete?'Play again':'Let’s play'} →</span></button>`).join('')}</div><p class="note">The order is a suggestion. Repeat, skip, pause, or use more help. Exploring a game does not establish mastery.</p></section><details class="quiet-notes sen-device"><summary>Progress on this device</summary><p>Only pathway activity and optional observations are stored in this browser. No name or diagnosis is collected. Original course progress is separate.</p><button class="secondary" id="senReset">Clear support-pathway progress</button></details>`;document.querySelector('#senLibrary').onclick=libraryHome;document.querySelector('#senLargerPictures').onchange=e=>{largerPictures=e.target.checked;document.body.classList.toggle('larger-pictures',largerPictures);try{localStorage.setItem('spotmatch-comfort',JSON.stringify(largerPictures));}catch{}};document.querySelector('#senStart').onclick=()=>senIntro(Math.max(0,c.games.findIndex((_,i)=>!senProgress[key]?.[i]?.complete)));document.querySelectorAll('[data-sen-game]').forEach(b=>b.onclick=()=>senIntro(+b.dataset.senGame));document.querySelector('#senReset').onclick=()=>{senProgress={};senSave();senHome(key);};senBindNav();window.scrollTo(0,0);}
function senDescription(p){if(typeof p==='string')return nameOf(p);if(p.icon)return nameOf(p.icon);if(p.scene!==undefined)return eventRoutines[p.scene].steps[p.stage].text;if(p.story!==undefined){const d=pictureStories[p.story];return [d.title+' — goal',d.title+' — problem',d.title+' — helpful action',d.title+' — ending'][p.stage];}if(p.type==='position')return `${nameOf(p.object)} ${p.position==='front'?'in front of':p.position} the ${nameOf(p.reference)}`;if(p.type==='actor')return `${p.actor||'bear'}: ${p.action}${p.object?' '+nameOf(p.object):''}`;if(p.type==='roles')return `${p.actor} ${p.action} ${p.object?nameOf(p.object)+' to ':''}${p.patient}`;if(p.type==='attribute')return `${p.value??p.size??''} ${p.attr} ${p.object?nameOf(p.object):'picture'}`;return 'Illustrated picture';}
function senGameArt(key,i){const game=supportPathways[key].games[i];if(game.kind==='mission'&&typeof Purposeful!=='undefined')return Purposeful.cover(game.mission);const t=senTask(key,i,0,0);return senPicture(t.reference?.[0]||t.pages?.[0]||t.options?.find(o=>t.answer.includes(o.id))?.picture||t.options?.[0]?.picture||t.banks?.[0]?.[0]||'book');}
function senShell(body){const key=senActive;app.innerHTML=`<div class="play-top"><button class="back" id="senBack">← Choose a game</button><span class="together-note">♧ Play together</span></div><section class="game-wrap friendly-play sen-play">${body}</section>`;document.querySelector('#senBack').onclick=()=>senHome(key);senBindNav();}
function senIntro(index){const c=supportPathways[senActive],g=c.games[index];senState={key:senActive,index,round:0,seed:nextPictureVisit('support-'+senActive,index),records:[],count:0,selected:[],done:false};senShell(`<span class="eyebrow">A LITTLE TIME TOGETHER</span><h1>${g.title}</h1><p>${senEscape(g.skill)}</p><div class="game-stage"><div class="adult-demo-picture">${senGameArt(senActive,index)}</div><p>An adult joins in. Point, sign, speak, or use your usual communication support.</p><button class="primary" id="senBegin">Let’s play together →</button></div><details class="quiet-notes"><summary>A little tip before you play</summary><p>${senEscape(g.tip||c.adapt)}</p><p>${senEscape(c.limit)}</p></details>`);document.querySelector('#senBegin').onclick=senPlay;}
const senChoice=(prompt,correct,others,reference=[])=>({mode:'choice',adult:prompt,options:shuffle([{id:'answer',picture:correct},...others.map((picture,i)=>({id:'other'+i,picture}))]),answer:['answer'],reference});
function senTask(key,index,r,seed){const g=supportPathways[key].games[index],n=(r+seed)%3;let t={mode:'explore',reference:[],options:[],answer:[],adult:'Explore together. There is no single right answer.',teach:g.tip,away:g.away};
 if(g.kind==='mapped'){const m=makeAdultTask(g.source,g.index,r,seed);return {...t,...m,teach:[g.tip,m.teach,g.source==='sounds'?m.adult:''].filter(Boolean).join(' '),soundGuide:g.source==='sounds',adult:g.source==='sounds'?friendlySoundInstruction({...m,index:g.index,round:r}):m.adult};}
 if(g.kind==='mission')return {...t,mode:'mission',mission:g.mission,adult:g.invitation};
 const opts=ids=>ids.map((picture,i)=>({id:String(i),picture}));
 if(g.kind==='placement'){const position=['in','on','under'][n];t={...t,mode:'place',adult:`Put the rabbit ${position} the box. Select the rabbit, then choose its new place.`,reference:['rabbit'],options:opts(['in','on','under'].map(position=>({type:'position',object:'rabbit',reference:'box',position}))),answer:[String(['in','on','under'].indexOf(position))]};}
 if(g.kind==='wordsteps'){const examples=[['Teddy sleeps.',2,'bear'],['Bunny holds a cup.',4,'rabbit'],['The cat jumps.',3,'cat']],a=examples[n];t={...t,mode:'counter',adult:`Say “${a[0]}” Use one pebble for each spoken word.`,reference:[a[2]],answer:[a[1]],teach:'Say the whole sentence first. Model one pebble per word, not per syllable or sound.'};}
 if(g.kind==='change'){const a=[['sun','fun','sun',['ball','cup']],['cat','hat','hat',['cat','dog']],['fish','dish','dish',['fish','shoe']]][n];t= {...t,...senChoice(`Say “${a[0]}”, then model “${a[1]}”. Change only the first sound. ${n===0?'Fun means having an enjoyable time: explore the change together.':`Which picture shows ${a[1]}?`}`,a[2],a[3])};if(n===0){t.mode='explore';t.options=opts(['sun','ball']);t.adult='Say “sun”. Change the first sound to /f/ to make “fun”. Explore the spoken change together; fun has no single object picture.';t.responses=['You can hear the change: sun → fun. Think of something enjoyable.','Playing with a ball can be fun. Say sun → fun together if helpful.'];}}
 if(g.kind==='actionvariety'){const actor=['bear','rabbit','cat'][n];t={...t,...senChoice(`The ${actor} is jumping. Find jumping in this new picture.`,{type:'actor',actor,action:'jump'},[{type:'actor',actor,action:'sleep'},{type:'actor',actor,action:'sit'}],[{type:'actor',actor:['rabbit','cat','bear'][n],action:'jump'}])};}
 if(['sequence','story','storymap','repeating','book','cause'].includes(g.kind)){const scene=[0,6,7][n],st=eventRoutines[scene];if(g.kind==='sequence'){const ids=[0,2];t={...t,mode:'order',adult:`What happens first, and what happens next? ${st.steps[0].text} ${st.steps[2].text}`,options:shuffle(ids.map(i=>({id:String(i),picture:{scene,stage:i}}))),answer:ids.map(String),teach:'Name and discuss both events. Choose them in time order. Pictures stay visible; this is not hidden-card memory.'};}else if(g.kind==='cause'){t.reference=[{scene,stage:0},{scene,stage:2}];t.options=opts([st.steps[1].icon,'hat','ball']);t.adult=`Look at the before and after pictures. ${st.steps[0].text} ${st.steps[2].text} What might have happened between them? Explore an idea together.`;t.responses=t.options.map(o=>o.picture===st.steps[1].icon?`In our story: ${st.steps[1].text}`:'Could that explain the change? Look at the clues and discuss. You can suggest something else.');}else{t.mode='book';t.pages=g.kind==='storymap'?[0,1,2,3].map(stage=>({story:n,stage})):[0,1,2].map(stage=>({scene,stage}));t.captions=g.kind==='storymap'?[`Our friend wants ${nameOf(pictureStories[n].goal)}.`,`A problem: ${nameOf(pictureStories[n].obstacle)}.`,`A helpful idea: ${nameOf(pictureStories[n].tool)}.`,`An ending: ${nameOf(pictureStories[n].outcome)}.`]:st.steps.map(s=>s.text);t.adult=g.kind==='repeating'?'Share this little story. Repeat a familiar phrase and invite the child to join in however they choose.':'Explore each page together, then tell the story in your own way.';}}
 if(g.kind==='tool'){const s=pictureStories[n];t={...t,...senChoice(`${s.explanation} What helps in this story?`,s.tool,['ball','hat'],[{story:n,stage:1}])};}
 if(g.kind==='clue'){const a=[['rain','umbrella','The umbrella is open and rain is falling. What clue tells us why the umbrella might help?'],['dark','flashlight','The room is dark. What clue tells us why a flashlight might help?'],['snow','coat','There is snow outside. What clue suggests a warm coat might help?']][n];t.reference=[a[0],a[1]];t.options=opts([a[0],'sun','ball']);t.adult=a[2];t.responses=t.options.map(o=>o.picture===a[0]?'That is a clue in this scene. Show or explain how the two pictures connect.':'Tell or show your idea. Does the scene give us evidence for it? Another explanation is welcome.');}
 if(g.kind==='possibilities'){t.reference=[{type:'actor',actor:'bear',action:'hold',object:['umbrella','book','basket'][n]}];t.options=opts(n===0?['rain','sun']:n===1?['bed','chair']:['apple','flower']);t.adult=['Bear is holding an umbrella. Might it be for rain, shade, or something else?','Bear is holding a book. Might Bear read in bed, on a chair, or somewhere else?','Bear is holding a basket. Might it carry food, flowers, or something else?'][n];t.responses=['That could be possible. What makes you think so?','That could be possible too. What else would help us know?'];}
 if(g.kind==='realobject'){const id=['cup','spoon','shoe'][n];t.reference=[id];t.options=opts([id,['ball','hat','apple'][n]]);t.adult=`Find a real ${nameOf(id)} if available. Explore it together, then choose its picture. If it is unavailable, explore the drawing and try the real-object link later.`;t.responses=t.options.map(o=>o.picture===id?'Compare the real object and this drawing. What is alike? They need not look exactly the same.':'Explore this picture too. Which drawing represents the object you have? Model the connection if useful.');}
 if(g.kind==='direction'){const a=[['cup','Pretend to drink from the cup.'],['brush','Show how the brush cleans a toy boot.'],['spoon','Put a real spoon in a bowl.']][n];t.reference=[a[0]];t.options=opts([a[0],'ball']);t.adult=`${a[1]} Use real objects if available; the pictures can help you talk about the action.`;t.responses=['Try the action together. A picture choice alone does not show the whole real-world action.','You can explore this too, then model the helpful action again.'];}
 if(g.kind==='transfer'){const id=['cup','hat','ball'][n];t.reference=[id];t.options=opts([{icon:id,variant:3},['shoe','apple','book'][n]]);t.adult=`Find another ${nameOf(id)} in your home or a family photograph. Compare it with this drawing. An on-screen choice is only part of this activity.`;t.responses=['Explore what makes these different examples the same kind of thing. Try the real-world example too.','Discuss how this differs. You can model the name and try a real object later.'];}
 if(g.kind==='contrast'){const a=[['cat','hat'],['boat','goat'],['fish','dish']][n];t={...t,...senChoice(`Name both pictures: ${a.join(', ')}. Say “${a[r%2]}”. Find that picture without needing to repeat it.`,a[r%2],[a[1-r%2]])};}
 if(g.kind==='message'){t.mode='compose';t.adult='Choose pictures for your own little story. Share your idea using speech, signs, or your usual AAC. You can change any part.';t.banks=[['bear','rabbit','cat'],['cup','ball','book'],['house','tree','bed']];}
 return t;
}
function senPlay(){const s=senState;s.task=senTask(s.key,s.index,s.round,s.seed);Object.assign(s,{play:null,count:0,selected:[],selection:null,done:false,hint:false,retries:0,page:0,composition:[null,null,null],reveal:false,observation:'not-recorded',response:''});senRender();window.scrollTo(0,0);}
function senRender(focusId){if(senState.task.mode==='mission'){Purposeful.render(focusId);return;}const s=senState,t=s.task,c=supportPathways[s.key],g=c.games[s.index];let body='';
 if(t.reference?.length)body+=`<div class="sen-reference">${t.reference.map(p=>`<div class="story-frame">${senPicture(p)}</div>`).join('')}</div>`;
 if(['explore','choice'].includes(t.mode)){const chosen=s.selection===null?null:t.options[s.selection],label=chosen?(g.kind==='theme'?['Trains','Animals','A picnic'][s.selection]:senDescription(chosen.picture)):'';body+=`<div id="senChoiceHome" class="tp-answer-pad sen-choice-home ${chosen?'has-choice':''}" role="group" aria-label="Your choice"><span class="sen-choice-heading">Your choice</span>${chosen?`<div class="sen-chosen-picture" role="img" aria-label="Chosen: ${senEscape(label)}">${senPicture(chosen.picture)}</div><span class="sen-choice-caption">${senEscape(label)}</span>`:'<span class="sen-choice-placeholder">Drag a picture here, or tap one below.</span>'}</div>`;}
 if(t.mode==='book'){body+=`<div class="sen-book" aria-label="Story page ${s.page+1} of ${t.pages.length}"><div class="story-frame">${senPicture(t.pages[s.page])}</div><p>${senEscape(t.captions[s.page])}</p><div class="sen-controls"><button class="secondary" id="senPageBack" ${s.page===0?'disabled':''}>← Previous page</button><span>${s.page+1} / ${t.pages.length}</span><button class="secondary" id="senPageNext" ${s.page===t.pages.length-1?'disabled':''}>Next page →</button></div></div>`;}
 else if(t.mode==='counter'){body+=`<div class="sen-pebbles" role="img" aria-label="${s.count} pebbles">${Array.from({length:6},(_,i)=>`<span class="sound-counter ${i<s.count?'filled':''}" aria-hidden="true"></span>`).join('')}</div><div class="sen-controls"><button id="senRemove" class="secondary" aria-label="Remove one pebble" ${s.count===0||s.done?'disabled':''}>−</button><button id="senAdd" class="primary" ${s.count===6||s.done?'disabled':''}>＋ A pebble</button></div>`;}
 else if(t.mode==='compose'){body+=`<div class="sen-story-slots">${s.composition.map((p,i)=>`<div class="story-frame" aria-label="Story part ${i+1}">${p?senPicture(p):'<span aria-hidden="true">＋</span>'}</div>`).join('')}</div>${t.banks.map((bank,i)=>`<div class="sen-compose-group" role="group" aria-label="Choose story part ${i+1}">${bank.map((p,j)=>`<button class="learning-option ${s.composition[i]===p?'selected':''}" data-compose="${i}:${j}" aria-label="Story part ${i+1}: ${nameOf(p)}" aria-pressed="${s.composition[i]===p}" ${s.done?'disabled':''}>${senPicture(p)}</button>`).join('')}</div>`).join('')}`;}
 else {if(t.mode==='place')body+=`<button class="secondary" id="senPick" aria-pressed="${s.reveal}" ${s.done?'disabled':''}>${s.reveal?'Rabbit selected ✓':'Choose rabbit'}</button>`;if(t.mode==='order')body+=`<div class="sen-story-slots" aria-label="Your story order">${t.answer.map((_,i)=>`<div class="story-frame">${s.selected[i]!==undefined?senPicture(t.options.find(o=>o.id===s.selected[i]).picture):`<span>${i+1}</span>`}</div>`).join('')}</div>`;body+=`<div class="learning-options sen-options">${t.options.map((o,i)=>`<button class="learning-option ${s.selection===i||s.selected.includes(o.id)?'selected':''} ${s.hint&&t.answer.includes(o.id)?'hinted':''}" data-sen-choice="${i}" aria-label="Picture ${i+1}: ${senEscape(senDescription(o.picture))}" aria-pressed="${s.selection===i||s.selected.includes(o.id)}" ${s.done||(t.mode==='order'&&s.selected.includes(o.id))||(t.mode==='place'&&!s.reveal)?'disabled':''}>${senPicture(o.picture)}</button>`).join('')}</div>`;}
 const open=['explore','book','compose'].includes(t.mode);const ready=t.mode==='counter'?true:t.mode==='order'?s.selected.length===t.answer.length:t.mode==='book'?s.page===t.pages.length-1:t.mode==='compose'?s.composition.every(Boolean):s.selection!==null;
 senShell(`<span class="eyebrow">${practiceRounds(3)===1?'ONE LITTLE EXPLORATION':`${s.round+1} OF ${practiceRounds(3)} LITTLE EXPLORATIONS`}</span><h1>${g.title}</h1><p class="play-invitation">${senEscape(t.adult)}</p>${t.soundGuide?'<p class="micro sen-sound-note">Name the pictures together first. Grown-up sound examples are in the tip below.</p>':''}<div class="game-stage sen-stage">${body}<div class="feedback" role="status" aria-live="polite">${senEscape(s.response)}</div><div class="sen-controls">${!s.done?`<button class="secondary" id="senHelp">A little help</button><button class="secondary" id="senClear">Start again</button><button class="primary" id="senCheck" ${ready?'':'disabled'}>${open?'We explored this →':'Let’s see ✓'}</button>`:`<button class="primary" id="senNext">${s.round+1===practiceRounds(3)?'All done →':'Next one →'}</button>`}</div></div><details class="quiet-notes" id="senTips"><summary>A little tip for grown-ups</summary><p>${senEscape(g.tip||c.adapt)}</p>${t.teach?`<p>${senEscape(t.teach)}</p>`:''}<p>${senEscape(c.adapt)}</p><p>${senEscape(c.limit)}</p><p>Correct selections can still involve help. Open-ended activities have no automatic right/wrong score.</p></details><details class="quiet-notes"><summary>Try it away from the screen</summary><p>${senEscape(g.away)}</p></details>${s.done?`<details class="quiet-notes"><summary>Optional grown-up observation</summary><label for="senObservation">What did you notice this time?</label><select id="senObservation"><option value="not-recorded">Leave unrecorded</option><option value="independent">Target skill shown without help</option><option value="supported">Target skill shown with help</option><option value="access">Input or access needed support</option><option value="not-yet">Not shown this time / unsure</option></select><p class="micro">Your observation, not an assessment. Access support and understanding are different.</p></details>`:''}`);
 const bind=(id,fn)=>{const el=document.getElementById(id);if(el)el.onclick=fn;};
 document.querySelectorAll('[data-sen-choice]').forEach(b=>b.onclick=()=>{const i=+b.dataset.senChoice;if(t.mode==='order')s.selected.push(t.options[i].id);else s.selection=i;s.response=t.responses?.[i]||'';senRender(t.mode==='order'?'senCheck':`choice:${i}`);});
 document.querySelectorAll('[data-compose]').forEach(b=>b.onclick=()=>{const [i,j]=b.dataset.compose.split(':').map(Number);s.composition[i]=t.banks[i][j];senRender('compose:'+b.dataset.compose);});
 bind('senPick',()=>{s.reveal=true;senRender('choice:0');});bind('senAdd',()=>{s.count++;senRender('senAdd');});bind('senRemove',()=>{s.count--;senRender('senRemove');});bind('senPageNext',()=>{s.page++;senRender(s.page===t.pages.length-1?'senCheck':'senPageNext');});bind('senPageBack',()=>{s.page--;senRender('senPageBack');});
 bind('senClear',()=>{Object.assign(s,{count:0,selected:[],selection:null,composition:[null,null,null],page:0,reveal:false,response:''});senRender('senClear');});
 bind('senHelp',()=>{s.hint=true;s.response=open?'Explore together. Model an idea, or try the activity with real objects.':'Here is a helping hand. Model the answer together, then try again.';senRender('senCheck');document.querySelector('#senTips').open=true;});
 bind('senCheck',()=>{const ok=open||(t.mode==='counter'?s.count===t.answer[0]:t.mode==='order'?JSON.stringify(s.selected)===JSON.stringify(t.answer):t.answer.includes(t.options[s.selection]?.id));if(ok){s.done=true;s.response=open?'A little idea to share.':'You found it. Explore the meaning together.';}else{s.retries++;s.response='Let’s take another look together. You can change your choice or ask for a little help.';if(t.mode==='order')s.selected=[];}senRender(ok?'senNext':'senCheck');});
 const observation=document.querySelector('#senObservation');if(observation){observation.value=s.observation;observation.onchange=()=>s.observation=observation.value;}
 bind('senNext',()=>{s.records.push({round:s.round,observation:s.observation,helpUsed:s.hint,retries:s.retries,kind:t.mode});s.round++;if(s.round>=practiceRounds(3))senFinish();else senPlay();});
 if(focusId){const el=focusId.startsWith('choice:')?document.querySelector(`[data-sen-choice="${focusId.split(':')[1]}"]`):focusId.startsWith('compose:')?document.querySelector(`[data-compose="${focusId.slice(8)}"]`):document.getElementById(focusId);if(el&&!el.disabled)el.focus({preventScroll:true});else if(t.mode==='order')document.querySelector('[data-sen-choice]:not(:disabled)')?.focus({preventScroll:true});}
}
function senFinish(){const s=senState;senProgress[s.key]??={};senProgress[s.key][s.index]={complete:true,records:s.records};senSave();const g=supportPathways[s.key].games[s.index];senShell(`<span class="eyebrow">A GOOD PLACE TO PAUSE</span><div class="completion-friend">${friendlyMascot()}</div><h1>Lovely exploring!</h1><p>A little discovery to take into your day.</p><p>${senEscape(g.away)}</p><div class="sen-controls"><button class="secondary" id="senAgain">Play this again</button><button class="primary" id="senAnother">${s.index<9?'Another little game →':'Choose another game →'}</button></div><details class="quiet-notes"><summary>For grown-ups · practice notes</summary><p>${s.records.length} exploration${s.records.length===1?'':'s'} finished. This records participation, not mastery or treatment benefit.</p><ul>${s.records.map((r,i)=>`<li>Exploration ${i+1}: ${{'not-recorded':'observation not recorded',independent:'adult observed target skill without help',supported:'adult observed target skill with help',access:'adult observed access support needed','not-yet':'not shown / unsure'}[r.observation]}; ${r.helpUsed?'teaching help used':'teaching help not selected'}; ${r.retries} checks revisited.</li>`).join('')}</ul><p>Progress stays in this browser. Original courses and their progress are preserved.</p></details>`);document.querySelector('#senAgain').onclick=()=>senIntro(s.index);document.querySelector('#senAnother').onclick=()=>s.index<9?senIntro(s.index+1):senHome(s.key);window.scrollTo(0,0);}
libraryHome();
